={{ /* v1-pc14-fu03-hotfix03-preface-gating */ (() => {
  const j = $json || {};
  const ms = String(j.memory_status || '').trim();
  const status = String(j.status || j.strict_surface_status || '').trim();
  const blocked =
    !!j.blocked_diagnostic ||
    ms === 'blocked_dirty' ||
    ms === 'blocked-dirty' ||
    status === 'blocked_dirty' ||
    status === 'blocked-dirty';
  if (blocked) {
    return "⚠️ Задача обработана, но итоговые материалы заблокированы строгой проверкой. Отправляю диагностическое сообщение...";
  }
  if (ms === 'failed' || ms === 'error' || status === 'error' || status === 'failed') {
    return "⚠️ Обработка завершена с ошибкой.\n\nПроверьте диагностику / статус.";
  }
  if (
    ms === 'approved_clean' ||
    ms === 'repair_attempted_clean' ||
    status === 'clean' ||
    status === 'approved_clean' ||
    status === 'repair_attempted_clean'
  ) {
    return "✅ Задача завершена\n\nРезультат готов. Отправляю материалы...";
  }
  return "Задача обработана. Проверяю итоговый статус перед отправкой...";
})() }}
